import {KEY,METRICS,defaults,emptyTotals,localDate,previousMonth,totals,change,validate,plan,sample,EXPENSE_CATEGORIES,EXPENSE_FREQUENCIES,financialSummary,financialPeriods,validExpense,CRM_KEY,manualOnly,CLIENT_SOURCES,clientName,validClient,withBusiness,revenueAttribution,migrateLegacyCRM,commissionSplit,sumCommissionSplits} from './model.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const amount=(n,unit='count')=>unit==='money'?new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',useGrouping:'always',minimumFractionDigits:2,maximumFractionDigits:2}).format(n):new Intl.NumberFormat('it-IT',{maximumFractionDigits:1}).format(n);
let state,storageError=false;try{const raw=localStorage.getItem(KEY);state=raw?validate(JSON.parse(raw)):sample();}catch{state={version:1,records:[],goals:{}};storageError=true;}
let baseState=manualOnly(state),migrationNotice='';
if(!baseState.legacyImported){try{const legacy=localStorage.getItem(CRM_KEY);if(legacy){baseState=migrateLegacyCRM(baseState,JSON.parse(legacy));validate(baseState);localStorage.setItem(KEY,JSON.stringify(baseState));migrationNotice='Anagrafiche e movimenti precedenti recuperati. Completa i dati mancanti dei clienti importati.';}else baseState.legacyImported=true;}catch{migrationNotice='Recupero del precedente archivio non completato: la copia originale è conservata senza modifiche. Puoi ripristinarne il backup da Clienti.';}}
let clientQuery='',clientSource='';
let financeMode='month',financeDay=localDate(),financeYear=localDate().slice(0,4);
let view='finance',month=localDate().slice(0,7),chartMetric='contacts',toastTimer;
const names={clients:'Clienti',business:'Vendite e provvigioni',finance:'Controllo economico',overview:'Panoramica',data:'Registro dati',actions:'Cosa fare',goals:'Obiettivi'};
const monthName=s=>new Date(s+'-01T12:00:00').toLocaleDateString('it-IT',{month:'long',year:'numeric'});
const dateLabel=s=>new Date(s+'T12:00:00').toLocaleDateString('it-IT',{day:'2-digit',month:'short',year:'numeric'});
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function refreshState(){state=withBusiness(baseState);}
function save(next){try{const clean=manualOnly(next);clean.legacyImported=true;validate(clean);localStorage.setItem(KEY,JSON.stringify(clean));baseState=clean;storageError=false;refreshState();render();return true;}catch(e){toast('Dati non salvati: '+e.message);return false;}}

function navigate(v){view=v;render()}
function render(){refreshState();document.title=`${names[view]} · Team Guzzetta Direzione`;$('#crumb').textContent=names[view];document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===view));const title={clients:['Le relazioni fanno la differenza.','Anagrafiche complete e provenienza dei clienti per attribuire ogni provvigione.'],business:['Più valore a ogni operazione.','Clienti, vendite e pagamenti: un solo inserimento, statistiche sempre aggiornate.'],finance:['Il tuo business,<br><em>in prospettiva.</em>','Incassi, spese e margini. Una visione economica da condividere.'],overview:['Ogni risultato racconta una storia.','Il tuo lavoro, tradotto in risultati e prossime opportunità.'],data:['Ogni risultato parte da un dato.','Registra il lavoro dell’agenzia e costruisci uno storico utile.'],actions:['Il prossimo passo, più chiaro.','Priorità calcolate sui tuoi risultati e sugli obiettivi del mese.'],goals:['Dai una direzione al mese.','Decidi cosa raggiungere. Misura i progressi, un giorno alla volta.']}[view];$('#main').innerHTML=`${storageError?'<div class="notice danger">Non è stato possibile leggere l’archivio. I dati originali non sono stati sovrascritti: ripristina un backup dal Registro dati.</div>':''}${state.demo?'<div class="notice"><span>✧</span> Stai esplorando dati e obiettivi dimostrativi. <button id="reset-demo">Inizia con i tuoi dati →</button></div>':''}<section class="page-heading"><div class="hero-copy"><div class="eyebrow"><span class="hero-live"></span> TEAM GUZZETTA <span class="hero-slash">/</span> BUSINESS INTELLIGENCE</div><h1>${title[0]}</h1><p>${title[1]}</p></div>${view==='clients'?'<button class="btn primary" id="new-client">＋ Nuovo cliente</button>':view==='business'?'<div class="movement-actions"><button class="btn income-action" id="new-income"><span>+</span> Registra incasso</button><button class="btn expense-action" id="new-expense-movement"><span>−</span> Registra spesa</button></div>':view==='overview'||view==='finance'?'':'<button class="btn primary" id="new-record">＋ Registra risultati</button>'}${heroArtwork()}</section><div class="period-bar ${(view==='finance'||view==='clients'||view==='business')?'hide-period':''}"><div class="period"><span>PERIODO DI ANALISI</span><label><input id="month" type="month" value="${month}" min="2000-01" max="2100-12" aria-label="Mese di analisi"></label></div><span class="period-note">${month===localDate().slice(0,7)?'Mese in corso · dati fino a oggi':'Periodo selezionato'} <i></i> ${state.records.filter(r=>r.date.startsWith(month)).length} registrazioni</span></div>${migrationNotice?`<div class="notice">${esc(migrationNotice)}</div>`:''}${view==='clients'?clientsView():view==='business'?businessView():view==='finance'?financeView():view==='overview'?overview():view==='data'?dataView():view==='actions'?actionsView():goalsView()}`;bind();}
function kpis(){const t=totals(state.records,month),prev=totals(state.records,previousMonth(month));return `<div class="kpis">${[['contacts','Nuovi contatti','+'],['appointments','Appuntamenti svolti','▤'],['mandates','Incarichi acquisiti','⌂'],['revenue','Provvigioni lorde','€']].map(([key,label,icon],i)=>{const unit=key==='revenue'?'money':'count',delta=change(t[key],prev[key]);return `<article class="kpi ${i===3?'featured':''}"><div class="kpi-label">${label}<span>${icon}</span></div><strong>${amount(t[key],unit)}</strong><div class="kpi-note">${delta===null?'<span class="neutral">—</span> Nessuna base nel mese precedente':`<span class="${delta>=0?'up':'down'}">${delta>=0?'+':''}${Math.round(delta)}%</span> sul mese precedente`}</div></article>`}).join('')}</div><p class="comparison-note">Confronto tra totali registrati nei due mesi. Il mese in corso può essere incompleto.</p>`}
function overview(){const t=totals(state.records,month),economic=financialSummary(state.records,state.expenseEntries||[],month);t.expenses=economic.expenses;const items=plan(state.records,state.goals,month);return kpis()+`<div class="dashboard-grid"><section class="panel chart-panel"><div class="panel-head"><div><h2>Il ritmo del tuo lavoro</h2><p>Risultati giorno per giorno · ${monthName(month)}</p></div><select id="chart-metric" aria-label="Indicatore del grafico">${METRICS.map(m=>`<option value="${m.key}" ${chartMetric===m.key?'selected':''}>${m.short}</option>`).join('')}</select></div>${chart()}<div class="chart-footer"><span><i></i> ${METRICS.find(m=>m.key===chartMetric).label}</span><span>Totale ${amount(t[chartMetric],METRICS.find(m=>m.key===chartMetric).unit)}</span></div></section><section class="panel priorities"><div class="panel-head"><div><div class="eyebrow small">DAL DATO ALL’AZIONE</div><h2>Dove concentrarti</h2></div><span class="spark">✧</span></div>${items.length?items.filter(x=>x.state!=='done').slice(0,3).map((x,i)=>priority(x,i)).join('')||'<div class="celebrate">Obiettivi raggiunti.<p>Valuta il prossimo mese e consolida i risultati.</p></div>':'<div class="empty">Imposta gli obiettivi del mese per ottenere priorità personalizzate.</div>'}<button class="text-btn" data-go="actions">Apri il piano di azione <span>→</span></button></section></div><div class="dashboard-grid bottom-grid"><section class="panel"><div class="panel-head"><div><h2>Dal contatto alla vendita</h2><p>Volumi del periodo per fase del lavoro.</p></div></div><div class="funnel">${['contacts','appointments','valuations','mandates','offers','sales'].map((key,i)=>{const metric=METRICS.find(m=>m.key===key),max=Math.max(...METRICS.filter(m=>m.unit==='count').map(m=>t[m.key]),1);return `<div class="funnel-row"><span class="step-number">0${i+1}</span><span>${metric.short}</span><div class="bar-track"><div style="width:${t[key]/max*100}%"></div></div><strong>${t[key]}</strong></div>`}).join('')}</div><p class="panel-footnote">Attività dello stesso periodo; non rappresentano il percorso degli stessi clienti né un tasso di conversione.</p></section><section class="panel finance"><div class="panel-head"><div><h2>Uno sguardo economico</h2><p>Incassi e spese che hai registrato.</p></div></div><div class="finance-line"><span>Provvigioni lorde incassate</span><strong>${amount(t.revenue,'money')}</strong></div><div class="finance-line"><span>RE/MAX Italia · 10%</span><strong>− ${amount(economic.italiaFee,'money')}</strong></div><div class="finance-line"><span>RE/MAX Platinum · 15% dopo Italia</span><strong>− ${amount(economic.platinumFee,'money')}</strong></div><div class="finance-line"><span>Altre spese pagate</span><strong>− ${amount(t.expenses,'money')}</strong></div><div class="finance-total"><span>Margine effettivo</span><strong>${amount(economic.margin,'money')}</strong></div><p class="panel-footnote">Provvigioni lorde meno RE/MAX Italia (10%), RE/MAX Platinum (15% dopo Italia) e altre spese. Non è l’utile fiscale.</p></section></div>`}
function chart(){const [y,m]=month.split('-').map(Number),days=new Date(y,m,0).getDate(),daily=Array.from({length:days},()=>0);for(const r of state.records.filter(r=>r.date.startsWith(month)))daily[Number(r.date.slice(8))-1]+=r[chartMetric];if(chartMetric==='expenses')for(const e of(state.expenseEntries||[]).filter(e=>e.date.startsWith(month)))daily[Number(e.date.slice(8))-1]+=e.amount;const max=Math.max(...daily,1),width=680,height=205,pad=36,bar=(width-pad-16)/days;return `<div class="chart-scroll"><svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(METRICS.find(x=>x.key===chartMetric).label)} giornalieri nel mese di ${esc(monthName(month))}">${[0,.5,1].map(f=>`<line x1="${pad}" x2="${width-10}" y1="${height-30-f*150}" y2="${height-30-f*150}" class="gridline"/><text x="${pad-9}" y="${height-26-f*150}" text-anchor="end" class="axis">${Math.round(max*f)}</text>`).join('')}${daily.map((v,i)=>`<rect x="${pad+i*bar+2}" y="${height-30-(v/max*150)}" width="${Math.max(2,bar-5)}" height="${v/max*150}" rx="3" class="chart-bar"><title>${i+1} ${monthName(month)}: ${amount(v,METRICS.find(x=>x.key===chartMetric).unit)}</title></rect>${i%5===0||i===days-1?`<text x="${pad+i*bar+bar/2}" y="${height-9}" text-anchor="middle" class="axis">${i+1}</text>`:''}`).join('')}</svg></div>`}
function priority(x,i){return `<div class="priority"><span class="priority-number">0${i+1}</span><div><strong>${x.state==='closed'?'Rivedi il risultato: ':x.state==='behind'?'Recupera il ritmo: ':'Continua su: '}${x.label.toLocaleLowerCase('it')}</strong><p>${x.state==='closed'?`Mese concluso: ${amount(x.gap,x.unit)} sotto l’obiettivo.`:`Mancano ${amount(x.gap,x.unit)} al tuo obiettivo mensile.`}</p></div><span class="priority-dot ${x.state}"></span></div>`}
const advice={contacts:'Programma contatti con nuove richieste e richiami dei lead già presenti, rispettando le loro preferenze di contatto.',appointments:'Ricontatta i clienti con una ricerca attiva e proponi visite a immobili compatibili con le loro esigenze.',valuations:'Proponi un incontro ai proprietari interessati a conoscere il valore del proprio immobile.',mandates:'Fai il punto sulle valutazioni aperte e concorda il prossimo incontro con i proprietari.',offers:'Verifica l’esito delle visite e chiarisci esigenze e condizioni dei clienti interessati.',sales:'Rivedi le trattative aperte, individua i documenti mancanti e concorda le prossime scadenze.',revenue:'Controlla le pratiche concluse e le scadenze delle provvigioni da incassare.'};
function actionsView(){const items=plan(state.records,state.goals,month);return `<div class="actions-intro"><span>◎</span><div><h2>Una priorità alla volta.</h2><p>Il piano confronta risultati e obiettivi con i giorni trascorsi nel mese. Le attività suggerite vanno adattate alle trattative reali.</p></div><button class="btn" data-go="goals">Modifica obiettivi</button></div>${items.length?`<div class="action-cards">${items.map((x,i)=>`<article class="panel action-card"><div class="action-card-top"><span>PRIORITÀ ${String(i+1).padStart(2,'0')}</span><span class="status ${x.state}">${{done:'Raggiunto',behind:'Da recuperare',track:'In linea',closed:'Mese concluso'}[x.state]}</span></div><h2>${x.label}</h2><div class="action-values"><strong>${amount(x.actual,x.unit)}</strong><span>/ ${amount(x.target,x.unit)}</span></div><div class="progress"><i style="width:${Math.min(100,x.progress*100)}%"></i></div><p>${x.state==='done'?'Obiettivo raggiunto. Consolida il risultato e prepara il prossimo periodo.':x.state==='closed'?`Il mese si è chiuso con un divario di ${amount(x.gap,x.unit)}. Usa lo storico per definire i prossimi obiettivi.`:`Mancano <b>${amount(x.gap,x.unit)}</b> in ${x.remaining} giorni di calendario. Ritmo richiesto: <b>${x.unit==='count'?new Intl.NumberFormat('it-IT',{maximumFractionDigits:2}).format(x.pace):amount(x.pace,'money')} ${'al giorno'}</b>.`}</p><div class="suggestion"><span>PROSSIMA AZIONE</span><p>${x.state==='done'?'Documenta ciò che ha funzionato e controlla le attività ancora aperte.':advice[x.key]}</p></div></article>`).join('')}</div>`:'<section class="panel empty">Non ci sono obiettivi attivi per questo mese.<br><button class="btn primary" data-go="goals">Imposta gli obiettivi</button></section>'}`}
function dataView(){const records=state.records.filter(r=>r.date.startsWith(month)).sort((a,b)=>b.date.localeCompare(a.date));return `<section class="panel"><div class="panel-head"><div><h2>Il registro dei risultati <span class="count">${records.length}</span></h2><p>Aggiungi una giornata o un singolo aggiornamento. Più registrazioni nello stesso giorno vengono sommate.</p></div><button class="btn" id="import">Ripristina backup</button></div><div class="table-wrap"><table><thead><tr><th>DATA</th>${METRICS.map(m=>`<th>${m.short.toUpperCase()}</th>`).join('')}<th>NOTE</th><th>AZIONI</th></tr></thead><tbody>${records.map(r=>`<tr><td>${dateLabel(r.date)}</td>${METRICS.map(m=>`<td>${amount(r[m.key],m.unit)}</td>`).join('')}<td class="notes">${esc(r.notes||'—')}</td><td>${r.source==='business'?'<button class="source-tag" data-go="business">Da movimenti ↗</button>':`<button class="icon-btn" data-edit="${esc(r.id)}" aria-label="Modifica registrazione">✎</button><button class="icon-btn" data-delete="${esc(r.id)}" aria-label="Elimina registrazione">×</button>`}</td></tr>`).join('')}</tbody></table></div>${records.length?'':'<div class="empty">Nessuna registrazione in questo mese. Aggiungi i primi risultati.</div>'}</section><p class="panel-footnote">Ogni aggiornamento si somma ai precedenti: modifica una registrazione per correggerla senza duplicare i valori.</p>`}
function goalsView(){const g=state.goals[month]||emptyTotals();return `<section class="panel goals-panel"><div class="panel-head"><div><h2>Obiettivi di ${monthName(month)}</h2><p>Definisci risultati mensili realistici per la tua agenzia. Un valore pari a zero disattiva quell’obiettivo.</p></div></div><form id="goals-form"><div class="goal-grid">${METRICS.filter(m=>m.key!=='expenses').map(m=>`<label class="field">${m.label}<input type="number" name="${m.key}" value="${g[m.key]}" min="0" step="${m.unit==='money'?'0.01':'1'}" required></label>`).join('')}</div><div class="form-actions"><span class="hint">Valori riferiti al solo mese selezionato.</span><button class="btn primary">Salva obiettivi</button></div></form></section>`}
function bind(){const on=(s,event,fn)=>{const e=$(s);if(e)e.addEventListener(event,fn)};on('#month','change',e=>{if(/^\d{4}-(0[1-9]|1[0-2])$/.test(e.target.value)){month=e.target.value;render()}});on('#new-record','click',()=>recordEditor());bindFinance();bindNative();on('#chart-metric','change',e=>{chartMetric=e.target.value;render()});on('#reset-demo','click',()=>confirm('Inizia con i tuoi dati','Saranno rimossi i risultati dimostrativi e gli obiettivi correnti. Saranno rimossi anche clienti e incassi di esempio non modificati. Le anagrafiche e i movimenti effettivi resteranno conservati. Esporta prima un backup per conservare gli inserimenti manuali.',()=>resetDemo()));on('#import','click',importBackup);on('#goals-form','submit',e=>{e.preventDefault();const values=Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,Number(v)]));const next=structuredClone(state);next.goals[month]=values;if(save(next))toast('Obiettivi salvati per '+monthName(month))});document.querySelectorAll('[data-go]').forEach(e=>e.onclick=()=>navigate(e.dataset.go));document.querySelectorAll('[data-edit]').forEach(e=>e.onclick=()=>recordEditor(e.dataset.edit));document.querySelectorAll('[data-delete]').forEach(e=>e.onclick=()=>confirm('Eliminare la registrazione?','I totali e le statistiche verranno ricalcolati.',()=>{const next=structuredClone(state);next.records=next.records.filter(r=>r.id!==e.dataset.delete);return save(next)}));}
const dialog=$('#dialog');
function open(title,html){$('#dialog-body').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-btn" id="close" aria-label="Chiudi">×</button></div>${html}`;$('#close').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal()}
function confirm(title,text,fn){open(title,`<p class="hint">${text}</p><div class="form-actions"><button class="btn" id="cancel">Annulla</button><button class="btn primary" id="confirm">Conferma</button></div>`);$('#cancel').onclick=()=>dialog.close();$('#confirm').onclick=()=>{if(fn()){dialog.close();toast('Operazione completata')}}}
function recordEditor(id){if(id&&state.records.find(r=>r.id===id)?.source==='business'){navigate('business');return}const r=state.records.find(r=>r.id===id)||{...emptyTotals(),date:month===localDate().slice(0,7)?localDate():month+'-01',notes:''};open(id?'Modifica risultati':'Registra risultati',`<form id="record-form"><label class="field">Data<input name="date" type="date" required value="${r.date}" max="${localDate()}" min="2000-01-01"></label><p class="hint">Inserisci solo le nuove attività di questa registrazione. I valori si aggiungono allo storico del giorno. Per le spese, usa questo modulo oppure il registro spese: non inserire lo stesso pagamento due volte.</p><div class="goal-grid">${METRICS.map(m=>`<label class="field">${m.label}<input type="number" name="${m.key}" value="${r[m.key]}" min="0" step="${m.unit==='money'?'0.01':'1'}" required></label>`).join('')}</div><label class="field">Note<textarea name="notes" maxlength="5000" placeholder="Contesto, campagne o dettagli da ricordare…">${esc(r.notes)}</textarea></label><div class="form-actions"><button type="button" class="btn" id="cancel">Annulla</button><button class="btn primary">Salva risultati</button></div></form>`);$('#cancel').onclick=()=>dialog.close();$('#record-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),values=Object.fromEntries(METRICS.map(m=>[m.key,Number(f.get(m.key))]));const next=structuredClone(state),record={...values,date:f.get('date'),notes:f.get('notes').trim(),id:id||crypto.randomUUID()};if(!METRICS.some(m=>record[m.key]>0)){toast('Inserisci almeno un risultato maggiore di zero.');return}if(id)next.records[next.records.findIndex(x=>x.id===id)]=record;else next.records.push(record);const targetMonth=record.date.slice(0,7);const oldMonth=month;month=targetMonth;if(save(next)){dialog.close();toast('Risultati salvati')}else month=oldMonth;};}
function exportBackup(){const url=URL.createObjectURL(new Blob([JSON.stringify(baseState,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`guzzetta-direzione-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup esportato')}
function importBackup(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files[0];if(!file)return;try{if(file.size>5e6)throw Error('Il file supera 5 MB.');const parsed=JSON.parse(await file.text());const next=Array.isArray(parsed.records)?validate(parsed):migrateLegacyCRM(baseState,parsed);confirm('Ripristinare il backup?',`Il backup contiene ${(next.clients||[]).length} clienti, ${(next.deals||[]).length} vendite, ${(next.cashEntries||[]).length} movimenti, ${next.records.length} registrazioni storiche e ${(next.expenseEntries||[]).length} spese dettagliate e sostituirà l’archivio del programma, inclusi clienti, vendite, movimenti e obiettivi. I dati derivati saranno ricalcolati senza duplicazioni. Esporta prima un backup per conservarli.`,()=>save(next));}catch(e){toast('Importazione non riuscita: '+e.message)}};input.click()}
document.querySelectorAll('[data-view]').forEach(e=>e.onclick=()=>navigate(e.dataset.view));$('#backup').onclick=exportBackup;render();

function financePrefix(){return financeMode==='day'?financeDay:financeMode==='year'?financeYear:month;}
function periodLabel(prefix,mode=financeMode){return mode==='day'?dateLabel(prefix):mode==='year'?`Anno ${prefix}`:monthName(prefix);}
function percent(value){return value===null?'n.d.':new Intl.NumberFormat('it-IT',{minimumFractionDigits:1,maximumFractionDigits:1}).format(value)+'%';}
function financeView(){
 const prefix=financePrefix(),expenses=state.expenseEntries||[],summary=financialSummary(state.records,expenses,prefix),rows=financialPeriods(state.records,expenses,financeMode,prefix),label=periodLabel(prefix);
 const previous=financeMode==='year'?String(Number(prefix)-1):financeMode==='month'?previousMonth(prefix):(()=>{const d=new Date(prefix+'T12:00:00');d.setDate(d.getDate()-1);return localDate(d)})();const prev=financialSummary(state.records,expenses,previous),marginChange=summary.margin-prev.margin;
 const ledger=expenses.filter(e=>e.date.startsWith(prefix)).sort((a,b)=>b.date.localeCompare(a.date));
 return `<section class="finance-toolbar"><div class="segmented" aria-label="Scala temporale">${[['day','Giorno'],['month','Mese'],['year','Anno']].map(([key,name])=>`<button data-finance-mode="${key}" aria-pressed="${financeMode===key}" class="${financeMode===key?'active':''}">${name}</button>`).join('')}</div><label class="finance-date">Periodo<input id="finance-date" aria-label="Periodo economico" type="${financeMode==='day'?'date':financeMode==='month'?'month':'number'}" value="${prefix}" ${financeMode==='year'?'min="2000" max="2100" step="1"':''}></label><div class="report-actions"><button class="btn" id="csv-report">Esporta CSV / Excel</button><button class="btn primary" id="print-report">Stampa / Salva PDF</button></div></section>
 <article id="finance-report"><div class="report-heading"><div class="report-identity"><div class="report-logo"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" fill="none"><path d="m7 29 25-20 25 20" stroke="#8d244a" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><path d="M14 30v24h15V37h10v17h12V30" stroke="#b08530" stroke-width="3" stroke-linejoin="round"/><path d="M42 13V7h8v12M8 59h48" stroke="#b08530" stroke-width="2" stroke-linecap="round"/></svg></div><div><div class="eyebrow">TEAM GUZZETTA · CONTROLLO DI GESTIONE</div><h2>Prospetto economico</h2><p>${esc(label)} <span>·</span> Euro <span>·</span> Quote RE/MAX incluse</p></div></div><div class="report-stamp">${state.demo?'DATI DIMOSTRATIVI':'REPORT GESTIONALE'}<small>Elaborato il ${dateLabel(localDate())}</small></div></div>
 <div class="kpis economic-kpis">${[['Provvigioni lorde',summary.revenue,'money','incassi'],['Altre spese pagate',summary.expenses,'money','spese'],['Margine effettivo',summary.margin,'money','margine'],['Margine sugli incassi',summary.marginPercent,'percent','percentuale']].map(([title,value,unit,key])=>`<section class="kpi ${key==='margine'?'featured':''}" data-economic="${key}"><div class="kpi-label">${title}<span>${{incassi:'+',spese:'−',margine:'=',percentuale:'%'}[key]}</span></div><strong class="${value!==null&&value<0?'negative':''}">${unit==='percent'?percent(value):amount(value,'money')}</strong><p>${{incassi:'Lordo prima delle quote RE/MAX',spese:'Escluse le quote RE/MAX automatiche',margine:'Netto RE/MAX meno altre spese',percentuale:summary.revenue===0?'Non calcolabile con incassi pari a zero':'Margine ÷ incassi × 100'}[key]}</p></section>`).join('')}</div>
 ${royaltyBreakdown(summary)}<div class="economic-callout ${summary.margin<0?'loss':''}"><span>${summary.margin<0?'!':'↔'}</span><div><strong>${summary.margin<0?'Le altre spese superano il netto dopo RE/MAX':summary.margin>0?'Il netto dopo RE/MAX copre le altre spese':'Netto dopo RE/MAX e altre spese sono in equilibrio'}</strong><p>Scostamento di ${amount(summary.margin,'money')}. ${financialSummary(state.records,expenses,previous).entries?`Variazione del margine rispetto al periodo precedente: ${marginChange>0?'+':''}${amount(marginChange,'money')}.`:'Nessuna registrazione nel periodo precedente per un confronto.'}</p></div></div>
 <div class="dashboard-grid report-grid"><section class="panel financial-chart"><div class="panel-head"><div><h2>Provvigioni nette e altre spese</h2><p>${financeMode==='year'?'Andamento mensile':financeMode==='month'?'Andamento giornaliero':'Movimenti del giorno'} · ${esc(label)}</p></div><div class="chart-legend"><span>Netto RE/MAX</span><span>Altre spese</span></div></div>${economicChart(rows)}<p class="panel-footnote">Netto dopo le quote RE/MAX automatiche a confronto con le altre spese registrate nel periodo.</p></section><section class="panel cost-breakdown"><div class="panel-head"><div><h2>Composizione delle altre spese</h2><p>Costi registrati, esclusi Italia e Platinum.</p></div></div>${summary.categories.length?`<div class="cost-list">${summary.categories.map(c=>`<div class="cost-row"><div><span>${esc(c.category)}</span><strong>${amount(c.amount,'money')}</strong></div><div class="cost-track"><i style="width:${c.amount/summary.expenses*100}%"></i></div></div>`).join('')}</div>`:'<div class="empty">Nessuna spesa nel periodo selezionato.</div>'}<div class="cost-total">Totale altre spese <strong>${amount(summary.expenses,'money')}</strong></div></section></div>
 <section class="panel financial-detail"><div class="panel-head"><div><h2>Dettaglio ${financeMode==='year'?'mensile':financeMode==='month'?'giornaliero':'del giorno'}</h2><p>Scostamento e margine calcolati sullo stesso periodo.</p></div></div><div class="table-wrap"><table class="financial-table"><thead><tr><th>PERIODO</th><th>LORDO</th><th>ITALIA 10%</th><th>PLATINUM 15% DOPO ITALIA</th><th>NETTO RE/MAX</th><th>ALTRE SPESE</th><th>MARGINE EFFETTIVO €</th><th>MARGINE %</th></tr></thead><tbody>${rows.map(r=>`<tr class="${financeMode==='month'&&!r.entries?'no-entries':''}"><td>${financeMode==='year'?monthName(r.period):dateLabel(r.period)}</td><td>${amount(r.revenue,'money')}</td><td>${amount(r.italiaFee,'money')}</td><td>${amount(r.platinumFee,'money')}</td><td>${amount(r.netRevenue,'money')}</td><td>${amount(r.expenses,'money')}</td><td class="${r.margin<0?'negative':''}">${amount(r.margin,'money')}</td><td>${percent(r.marginPercent)}</td></tr>`).join('')}</tbody><tfoot><tr><td>TOTALE PERIODO</td><td>${amount(summary.revenue,'money')}</td><td>${amount(summary.italiaFee,'money')}</td><td>${amount(summary.platinumFee,'money')}</td><td>${amount(summary.netRevenue,'money')}</td><td>${amount(summary.expenses,'money')}</td><td class="${summary.margin<0?'negative':''}">${amount(summary.margin,'money')}</td><td>${percent(summary.marginPercent)}</td></tr></tfoot></table></div>${financeMode==='month'?'<button class="text-btn toggle-empty" id="toggle-empty">Mostra anche i giorni senza registrazioni</button>':''}</section>
 ${attributionReport(prefix)}<div class="methodology"><h3>Criteri di lettura</h3><p><b>RE/MAX Italia</b> = 10% delle provvigioni lorde. <b>RE/MAX Platinum</b> = 15% del residuo dopo Italia. <b>Margine effettivo (€)</b> = lordo − Italia − Platinum − altre spese. Le due quote sono calcolate su ogni incasso, arrotondate ai centesimi e poi sommate; non vengono salvate come nuovi pagamenti. <b>Margine (%)</b> = margine ÷ provvigioni lorde × 100; con incassi pari a zero la percentuale è “n.d.”. Il totale percentuale è ricalcolato sui totali, non è la media delle percentuali giornaliere.</p><p>Fonte: vendite e pagamenti registrati nel programma, più eventuali inserimenti storici. Le provvigioni sono attribuite all’anagrafica e alla fonte attualmente associate al cliente. Le spese già presenti nel Registro risultati sono incluse una sola volta nei totali, oltre ai pagamenti nel Registro spese. Frequenza e categoria descrivono il pagamento e non generano rate future. I periodi senza registrazioni mostrano zero e non attestano l’assenza di movimenti.</p><p>Il margine include quote RE/MAX calcolate automaticamente e le altre spese registrate: non attesta che le quote siano già state pagate e non è un bilancio fiscale né un utile netto. IVA, imposte, ammortamenti e altri costi sono considerati solo se inclusi negli importi registrati. ${state.demo?'<b>Questo report contiene dati dimostrativi e non rappresenta i risultati reali del Team Guzzetta.</b>':''}</p></div></article>
 <section class="panel expense-ledger"><div class="panel-head"><div><div class="eyebrow small">REGISTRO SPESE</div><h2>Ogni costo, sotto controllo</h2><p>Registra solo le altre spese: Italia e Platinum sono già detratti automaticamente. Non duplicare costi del Registro risultati.</p></div><button class="btn primary" id="new-expense">＋ Aggiungi spesa</button></div><div class="table-wrap"><table><thead><tr><th>DATA PAGAMENTO</th><th>DESCRIZIONE</th><th>CATEGORIA</th><th>FREQUENZA</th><th>INCASSO LORDO</th><th>SPESA PAGATA</th><th>AZIONI</th></tr></thead><tbody>${ledger.map(e=>`<tr><td>${dateLabel(e.date)}</td><td class="notes">${esc(e.description)}</td><td>${esc(e.category)}</td><td><span class="frequency">${esc(e.frequency)}</span></td><td>${amount(e.amount,'money')}</td><td>${e.source==='business'?'<button class="source-tag" data-go="business">Da movimenti ↗</button>':`<button class="icon-btn" data-edit-expense="${esc(e.id)}" aria-label="Modifica spesa">✎</button><button class="icon-btn" data-delete-expense="${esc(e.id)}" aria-label="Elimina spesa">×</button>`}</td></tr>`).join('')}</tbody></table></div>${ledger.length?'':'<div class="empty">Non hai ancora aggiunto spese dettagliate in questo periodo.</div>'}${summary.legacyExpenses?`<div class="legacy-note">Sono inclusi nel report anche ${amount(summary.legacyExpenses,'money')} di spese del Registro risultati. Per correggerle, modifica la registrazione originale.</div>`:''}</section>`;
}
function economicChart(rows){const w=760,h=230,pad=56,baseline=190,max=Math.max(1,...rows.map(r=>Math.max(r.netRevenue,r.expenses))),slot=(w-pad-14)/rows.length,bar=Math.min(30,slot*.29);return `<div class="chart-scroll"><svg class="chart economic-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Confronto tra netto RE/MAX e altre spese per ${esc(periodLabel(financePrefix()))}">${[0,.5,1].map(f=>`<line x1="${pad}" x2="${w-10}" y1="${baseline-f*155}" y2="${baseline-f*155}" class="gridline"/><text x="${pad-9}" y="${baseline-f*155+4}" text-anchor="end" class="axis">${new Intl.NumberFormat('it-IT',{notation:'compact',maximumFractionDigits:1}).format(max*f)}</text>`).join('')}${rows.map((r,i)=>{const x=pad+slot*i+slot/2;return `<g><title>${r.period}: netto RE/MAX ${amount(r.netRevenue,'money')}, spese ${amount(r.expenses,'money')}</title><rect x="${x-bar-1}" y="${baseline-r.netRevenue/max*155}" width="${bar}" height="${r.netRevenue/max*155}" rx="2" class="income-bar"/><rect x="${x+1}" y="${baseline-r.expenses/max*155}" width="${bar}" height="${r.expenses/max*155}" rx="2" class="expense-bar"/>${rows.length<=12||i%5===0||i===rows.length-1?`<text x="${x}" y="215" text-anchor="middle" class="axis">${financeMode==='year'?new Date(r.period+'-01T12:00:00').toLocaleDateString('it-IT',{month:'short'}):r.period.slice(8)}</text>`:''}</g>`}).join('')}</svg></div>`}
function bindFinance(){if(view!=='finance')return;document.querySelectorAll('[data-finance-mode]').forEach(e=>e.onclick=()=>{financeMode=e.dataset.financeMode;render()});$('#finance-date').onchange=e=>{const v=e.target.value;if(financeMode==='day'&&/^\d{4}-\d{2}-\d{2}$/.test(v))financeDay=v;else if(financeMode==='month'&&/^\d{4}-(0[1-9]|1[0-2])$/.test(v))month=v;else if(financeMode==='year'&&/^\d{4}$/.test(v)&&Number(v)>=2000&&Number(v)<=2100)financeYear=v;render()};const toggle=$('#toggle-empty');if(toggle)toggle.onclick=()=>{const show=$('#finance-report').classList.toggle('show-empty');toggle.textContent=show?'Nascondi i giorni senza registrazioni':'Mostra anche i giorni senza registrazioni'};$('#new-expense').onclick=()=>expenseEditor();$('#print-report').onclick=()=>window.print();$('#csv-report').onclick=exportFinancialCSV;document.querySelectorAll('[data-edit-expense]').forEach(e=>e.onclick=()=>expenseEditor(e.dataset.editExpense));document.querySelectorAll('[data-delete-expense]').forEach(e=>e.onclick=()=>confirm('Eliminare questa spesa?','Il pagamento verrà rimosso e il margine sarà ricalcolato in tutti i periodi.',()=>{const next=structuredClone(state);next.expenseEntries=(next.expenseEntries||[]).filter(x=>x.id!==e.dataset.deleteExpense);return save(next)}));}
function expenseEditor(id){if(id&&(state.expenseEntries||[]).find(e=>e.id===id)?.source==='business'){navigate('business');return}const item=(state.expenseEntries||[]).find(e=>e.id===id)||{date:localDate(),description:'',amount:'',category:EXPENSE_CATEGORIES[0],frequency:'Una tantum'};open(id?'Modifica spesa':'Nuova spesa',`<form id="expense-form"><div class="goal-grid"><label class="field">Data del pagamento<input type="date" name="date" required min="2000-01-01" max="${localDate()}" value="${item.date}"></label><label class="field">Importo pagato (€)<input type="number" name="amount" min="0.01" step="0.01" required value="${item.amount}"></label><label class="field">Categoria<select name="category">${EXPENSE_CATEGORIES.map(c=>`<option ${c===item.category?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label class="field">Frequenza del costo<select name="frequency">${EXPENSE_FREQUENCIES.map(f=>`<option ${f===item.frequency?'selected':''}>${f}</option>`).join('')}</select></label></div><label class="field expense-description">Descrizione<input name="description" maxlength="250" required value="${esc(item.description)}" placeholder="Es. canone ufficio, portale immobiliare, trasferta…"></label><p class="hint">Il pagamento viene conteggiato una sola volta alla data indicata. La frequenza non genera altri addebiti. Non inserire qui le quote RE/MAX automatiche o costi già nel Registro risultati.</p><div class="form-actions"><button type="button" class="btn" id="cancel">Annulla</button><button class="btn primary">Salva spesa</button></div></form>`);$('#cancel').onclick=()=>dialog.close();$('#expense-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),expense={id:id||crypto.randomUUID(),date:f.get('date'),amount:Number(f.get('amount')),category:f.get('category'),frequency:f.get('frequency'),description:f.get('description').trim()};if(!validExpense(expense)){toast('Controlla data, importo e descrizione della spesa.');return}const next=structuredClone(state);next.expenseEntries=next.expenseEntries||[];if(id)next.expenseEntries[next.expenseEntries.findIndex(x=>x.id===id)]=expense;else next.expenseEntries.push(expense);const before={month,financeYear,financeDay};month=expense.date.slice(0,7);financeYear=expense.date.slice(0,4);financeDay=expense.date;if(save(next)){dialog.close();toast('Spesa salvata e margini aggiornati')}else({month,financeYear,financeDay}=before);};}
function exportFinancialCSV(){const prefix=financePrefix(),expenses=state.expenseEntries||[],summary=financialSummary(state.records,expenses,prefix),rows=financialPeriods(state.records,expenses,financeMode,prefix),attribution=revenueAttribution(baseState,prefix);const numeric=n=>Number(n).toFixed(2).replace('.',',');const safe=v=>{const text=String(v);return '"'+(/^[-]?\d+,\d{2}$/.test(text)?text:text.replace(/^[=+@\-\t\r]/,"'$&")).replace(/"/g,'""')+'"'};
 const financialCells=r=>[numeric(r.revenue),numeric(r.italiaFee),numeric(r.platinumFee),numeric(r.netRevenue),numeric(r.expenses),numeric(r.margin),r.marginPercent===null?'n.d.':numeric(r.marginPercent)];const splitCells=r=>[numeric(r.gross),numeric(r.italiaFee),numeric(r.platinumFee),numeric(r.netRevenue)];
 const lines=[['TEAM GUZZETTA — PROSPETTO ECONOMICO'],['Periodo',periodLabel(prefix)],['Natura dati',state.demo?'DATI DIMOSTRATIVI':'Clienti, provvigioni e inserimenti storici'],['Criterio','Italia = 10% del lordo; Platinum = 15% dopo Italia; margine effettivo = netto dopo RE/MAX meno altre spese'],['Arrotondamento','Ogni quota arrotondata ai centesimi per singolo incasso, poi sommata nel periodo'],['Elaborato il',localDate()],[],['Periodo','Lordo EUR','RE/MAX Italia 10% EUR','RE/MAX Platinum 15% dopo Italia EUR','Netto RE/MAX EUR','Altre spese EUR','Margine effettivo EUR','Margine su lordo %'],...rows.map(r=>[r.period,...financialCells(r)]),['TOTALE',...financialCells(summary)],[],['Altra spesa','Importo EUR'],...summary.categories.map(c=>[c.category,numeric(c.amount)]),[],['PROVVIGIONI PER CLIENTE E PROVENIENZA'],['Cliente','Provenienza','Dettaglio fonte','Pagamenti','Lordo EUR','Italia EUR','Platinum EUR','Netto RE/MAX EUR'],...attribution.byClient.map(c=>[c.name,c.source,c.sourceDetails,c.count,...splitCells(c)]),['Incassi storici senza cliente','','','',...splitCells(attribution.unattributedBreakdown)],[],['PROVENIENZA','Lordo EUR','Italia EUR','Platinum EUR','Netto RE/MAX EUR'],...attribution.bySource.map(s=>[s.source,...splitCells(s)]),[],['Nota','Le quote RE/MAX sono calcolate automaticamente: non reinserirle nelle altre spese. Il report non attesta il loro pagamento e non è un bilancio fiscale.']];const csv='\uFEFF'+lines.map(row=>row.map(safe).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`Team-Guzzetta-Report-${prefix}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Report CSV esportato per Excel');}

window.addEventListener('storage',event=>{if(event.key===KEY&&event.newValue){try{baseState=manualOnly(validate(JSON.parse(event.newValue)));render()}catch{toast('L’archivio aggiornato in un’altra scheda non è leggibile.')}}});

function clientRevenue(id,prefix=''){return (baseState.cashEntries||[]).filter(c=>c.type==='income'&&c.clientId===id&&c.date.startsWith(prefix)).reduce((n,c)=>n+Math.round(c.amount*100),0)/100}
function clientAddress(c){return [c.address,c.postalCode,c.city,c.province].filter(Boolean).join(' · ')}
function clientsView(){const clients=(state.clients||[]).filter(c=>(!clientSource||c.source===clientSource)&&[clientName(c),c.address,c.city,c.phone,c.email,c.source,c.sourceDetails].join(' ').toLocaleLowerCase('it').includes(clientQuery.toLocaleLowerCase('it')));return `<section class="panel"><div class="panel-head"><div><h2>Anagrafiche clienti <span class="count">${(state.clients||[]).length}</span></h2><p>Dati personali, provenienza e totale delle provvigioni effettivamente incassate.</p></div><button class="btn" id="import-clients">Ripristina backup</button></div><div class="client-toolbar"><label class="field search-client">Cerca cliente<input id="client-query" value="${esc(clientQuery)}" placeholder="Nome, cognome, indirizzo, telefono o email"></label><label class="field">Provenienza<select id="client-source-filter"><option value="">Tutte le fonti</option>${CLIENT_SOURCES.map(s=>`<option ${clientSource===s?'selected':''}>${s}</option>`).join('')}</select></label></div><div class="table-wrap"><table class="client-table"><thead><tr><th>CLIENTE</th><th>INDIRIZZO</th><th>CONTATTI</th><th>PROVENIENZA</th><th>LORDO INCASSATO</th><th>NETTO RE/MAX</th><th></th></tr></thead><tbody>${clients.map(c=>`<tr><td><button class="client-name-btn" data-client="${esc(c.id)}">${esc(clientName(c))}</button>${c.legacyIncomplete?'<small class="incomplete-label">Anagrafica da completare</small>':''}</td><td class="notes">${esc(clientAddress(c)||'Da completare')}</td><td><a href="tel:${esc(c.phone)}">${esc(c.phone||'Telefono da completare')}</a><br><a href="mailto:${esc(c.email)}">${esc(c.email||'Email da completare')}</a></td><td><span class="source-pill">${esc(c.source||'Da completare')}</span><small class="client-source-detail">${esc(c.sourceDetails)}</small></td><td class="client-income">${amount(clientRevenue(c.id),'money')}</td><td>${amount(clientNet(c.id),'money')}</td><td><button class="icon-btn" data-edit-client="${esc(c.id)}" aria-label="Modifica cliente">✎</button></td></tr>`).join('')}</tbody></table></div>${clients.length?'':'<div class="empty">Nessun cliente trovato. Aggiungi la prima anagrafica o modifica i filtri.</div>'}<p class="panel-footnote">Gli incassi per cliente coprono tutto lo storico. Il prospetto economico mostra invece il periodo selezionato.</p></section>`}
function clientEditor(id){const c=(state.clients||[]).find(c=>c.id===id)||{firstName:'',lastName:'',address:'',city:'',postalCode:'',province:'',phone:'',email:'',source:'',sourceDetails:'',notes:''};const field=(key,label,type='text',required=false)=>`<label class="field">${label}${required?' *':''}<input name="${key}" type="${type}" maxlength="${key==='address'?250:150}" value="${esc(c[key])}" ${required?'required':''} ${key==='phone'?'autocomplete="tel" inputmode="tel"':key==='firstName'?'autocomplete="given-name"':key==='lastName'?'autocomplete="family-name"':key==='address'?'autocomplete="street-address"':key==='email'?'autocomplete="email"':''}></label>`;open(id?'Modifica anagrafica':'Nuovo cliente',`<form id="client-form">${c.legacyIncomplete?'<p class="hint">Dati recuperati dal precedente archivio. Controlla la separazione tra nome e cognome e completa i campi mancanti.</p>':''}<div class="goal-grid">${field('firstName','Nome','text',true)}${field('lastName','Cognome','text',true)}<div class="full-field">${field('address','Indirizzo completo','text',true)}</div>${field('city','Città')}${field('postalCode','CAP')}${field('province','Provincia')}${field('phone','Telefono','tel',true)}<div class="full-field">${field('email','Email','email',true)}</div><label class="field">Provenienza del cliente *<select name="source" required><option value="">Scegli la fonte</option>${CLIENT_SOURCES.map(s=>`<option ${c.source===s?'selected':''}>${s}</option>`).join('')}</select></label>${field('sourceDetails','Dettaglio fonte / segnalatore')}<label class="field full-field">Note<textarea name="notes" maxlength="5000">${esc(c.notes)}</textarea></label></div><div class="form-actions"><button type="button" class="btn" id="cancel">Annulla</button><button class="btn primary">Salva cliente</button></div></form>`);$('#cancel').onclick=()=>dialog.close();$('#client-form').onsubmit=e=>{e.preventDefault();const value=Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,v.trim()]));value.id=id||crypto.randomUUID();value.legacyIncomplete=false;if(!validClient(value)){toast('Completa nome, cognome, indirizzo, telefono, email e provenienza.');return}const next=structuredClone(state);next.clients=next.clients||[];if(id)next.clients[next.clients.findIndex(x=>x.id===id)]=value;else next.clients.push(value);if(save(next)){dialog.close();toast('Anagrafica e provenienza salvate')}};}
function clientDetail(id){const c=(state.clients||[]).find(c=>c.id===id);if(!c)return;const payments=(state.cashEntries||[]).filter(p=>p.type==='income'&&p.clientId===id).sort((a,b)=>b.date.localeCompare(a.date));open(esc(clientName(c)),`<dl class="client-details"><div><dt>Indirizzo</dt><dd>${esc(clientAddress(c)||'Da completare')}</dd></div><div><dt>Telefono</dt><dd>${esc(c.phone||'Da completare')}</dd></div><div><dt>Email</dt><dd>${esc(c.email||'Da completare')}</dd></div><div><dt>Provenienza</dt><dd>${esc(c.source||'Da completare')}${c.sourceDetails?' · '+esc(c.sourceDetails):''}</dd></div></dl><div class="client-income-total"><span>Provvigioni lorde · tutto lo storico</span><strong>${amount(clientRevenue(id),'money')}</strong><small>Netto dopo Italia e Platinum: ${amount(clientNet(id),'money')} · prima delle altre spese</small></div><div class="client-payments">${payments.map(p=>`<div><span>${dateLabel(p.date)} · ${esc(p.description)}</span><strong>${amount(p.amount,'money')}</strong></div>`).join('')||'<p class="hint">Nessuna provvigione incassata associata a questo cliente.</p>'}</div><div class="form-actions"><button class="btn" id="edit-client-detail">Modifica anagrafica</button><button class="btn primary" id="collect-client">Registra provvigione</button><button class="btn" id="remove-client">Elimina cliente</button></div>`);$('#edit-client-detail').onclick=()=>clientEditor(id);$('#collect-client').onclick=()=>cashEditor(null,'',id);$('#remove-client').onclick=()=>{if((state.cashEntries||[]).some(p=>p.clientId===id)||(state.deals||[]).some(d=>d.clientId===id)){toast('Il cliente ha vendite o pagamenti collegati: mantieni l’anagrafica per conservarne la provenienza.');return}confirm('Eliminare il cliente?','L’anagrafica non ha movimenti collegati e sarà rimossa.',()=>{const next=structuredClone(state);next.clients=next.clients.filter(x=>x.id!==id);return save(next)})};}
function businessView(){const deals=state.deals||[],cash=state.cashEntries||[],name=id=>clientName((state.clients||[]).find(c=>c.id===id));return `<section class="panel native-sales"><div class="panel-head"><div><h2>Vendite e provvigioni previste</h2><p>La vendita aggiorna il numero delle operazioni. L’incasso si registra solo quando il pagamento è ricevuto.</p></div><button class="btn" id="new-deal">＋ Nuova vendita</button></div>${deals.length?`<div class="table-wrap"><table><thead><tr><th>IMMOBILE / RIFERIMENTO</th><th>CLIENTE</th><th>STATO</th><th>LORDO PREVISTO</th><th>LORDO INCASSATO</th><th>AZIONI</th></tr></thead><tbody>${deals.map(d=>`<tr><td>${esc(d.title)}<br><small>${dateLabel(d.date)}</small></td><td>${esc(name(d.clientId))}</td><td>${esc(d.status)}</td><td>${amount(d.commission,'money')}</td><td>${amount(cash.filter(p=>p.type==='income'&&p.dealId===d.id).reduce((n,p)=>n+Math.round(p.amount*100),0)/100,'money')}</td><td><button class="btn" data-collect="${esc(d.id)}">Registra incasso</button><button class="icon-btn" data-deal="${esc(d.id)}" aria-label="Modifica vendita">✎</button><button class="icon-btn" data-delete-deal="${esc(d.id)}" aria-label="Elimina vendita">×</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nessuna vendita registrata. Puoi registrare anche una provvigione direttamente per cliente.</div>'}</section><section class="panel native-movements"><div class="panel-head"><div><h2>Provvigioni incassate e spese pagate</h2><p>Incassi e spese sono registrazioni separate, anche nella stessa giornata. Il margine considera entrambi; le quote RE/MAX si applicano solo agli incassi.</p></div></div>${cash.length?`<div class="table-wrap"><table><thead><tr><th>DATA</th><th>MOVIMENTO</th><th>CLIENTE / FONTE</th><th>INCASSO LORDO</th><th>SPESA PAGATA</th><th>AZIONI</th></tr></thead><tbody>${[...cash].sort((a,b)=>b.date.localeCompare(a.date)).map(p=>{const c=(state.clients||[]).find(c=>c.id===p.clientId);return `<tr><td>${dateLabel(p.date)}</td><td><span class="movement-badge ${p.type}">${p.type==='income'?'+ Incasso':'− Spesa'}</span><br><small>${esc(p.description)}</small></td><td>${p.type==='income'?`${esc(clientName(c))}<br><span class="source-pill">${esc(c?.source||'Da completare')}</span>`:esc(p.category)}</td><td class="income-column">${p.type==='income'?`${amount(p.amount,'money')}<br><small>Netto RE/MAX: ${amount(commissionSplit(p.amount).netRevenue,'money')}</small>`:'—'}</td><td class="expense-column">${p.type==='expense'?'− '+amount(p.amount,'money'):'—'}</td><td><button class="icon-btn" data-cash="${esc(p.id)}" aria-label="Modifica movimento">✎</button><button class="icon-btn" data-delete-cash="${esc(p.id)}" aria-label="Elimina movimento">×</button></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">Nessun movimento registrato.</div>'}</section>`}
function dealEditor(id){const d=(state.deals||[]).find(d=>d.id===id)||{title:'',date:localDate(),clientId:'',status:'Conclusa',commission:0};open(id?'Modifica vendita':'Nuova vendita',`<form id="deal-form"><div class="goal-grid"><label class="field">Immobile / riferimento *<input name="title" required maxlength="250" value="${esc(d.title)}"></label><label class="field">Data vendita *<input name="date" type="date" required value="${d.date}"></label><label class="field full-field">Cliente *<select name="clientId" required><option value="">Seleziona il cliente</option>${(state.clients||[]).map(c=>`<option value="${esc(c.id)}" ${d.clientId===c.id?'selected':''}>${esc(clientName(c))}</option>`).join('')}</select></label><label class="field">Stato<select name="status">${['In trattativa','Conclusa','Annullata'].map(x=>`<option ${d.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Provvigione lorda prevista (€)<input name="commission" type="number" min="0" step="0.01" value="${d.commission}" required></label></div><p class="hint">La provvigione prevista non è ancora incassata. Usa “Registra incasso” quando ricevi il pagamento.</p><div class="form-actions"><button class="btn" type="button" id="cancel">Annulla</button><button class="btn primary">Salva vendita</button></div></form>`);$('#cancel').onclick=()=>dialog.close();$('#deal-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),value={id:id||crypto.randomUUID(),title:f.get('title').trim(),date:f.get('date'),clientId:f.get('clientId'),status:f.get('status'),commission:Number(f.get('commission'))};if(id&&(state.cashEntries||[]).some(p=>p.dealId===id&&p.clientId&&p.clientId!==value.clientId)){toast('La vendita ha pagamenti associati a un altro cliente. Correggi prima i collegamenti dei movimenti.');return}const next=structuredClone(state);next.deals=next.deals||[];if(id)next.deals[next.deals.findIndex(x=>x.id===id)]=value;else next.deals.push(value);if(save(next)){dialog.close();toast('Vendita salvata e statistiche aggiornate')}};}
function cashEditor(id,dealId='',clientId='',kind='income'){const deal=(state.deals||[]).find(d=>d.id===dealId),p=(state.cashEntries||[]).find(p=>p.id===id)||{type:kind,date:localDate(),description:deal?'Provvigione · '+deal.title:'',amount:'',dealId,clientId:clientId||deal?.clientId||'',category:'Altro',frequency:'Una tantum'};open(p.type==='income'?(id?'Modifica incasso':'Registra incasso'):(id?'Modifica spesa':'Registra spesa'),`<form id="cash-form" data-kind="${p.type}"><input type="hidden" name="type" value="${p.type}"><div class="movement-kind ${p.type}"><span>${p.type==='income'?'+':'−'}</span><div><strong>${p.type==='income'?'ENTRATA · PROVVIGIONE INCASSATA':'USCITA · SPESA PAGATA'}</strong><p>${p.type==='income'?'Registra il lordo ricevuto dal cliente. Le quote RE/MAX vengono calcolate automaticamente.':'Registra solo l’importo pagato. A questa uscita non si applicano quote RE/MAX.'}</p></div></div><div class="goal-grid"><label class="field">Data del pagamento *<input name="date" type="date" required max="${localDate()}" value="${p.date}"></label><label class="field full-field">Descrizione *<input name="description" required maxlength="250" value="${esc(p.description)}"></label><label class="field">${p.type==='income'?'Provvigione lorda incassata (€)':'Importo della spesa pagata (€)'} *<input name="amount" type="number" min="0.01" step="0.01" required value="${p.amount}"></label><label class="field income-only">Cliente della provvigione *<select name="clientId"><option value="">Seleziona il cliente</option>${(state.clients||[]).map(c=>`<option value="${esc(c.id)}" ${p.clientId===c.id?'selected':''}>${esc(clientName(c))}</option>`).join('')}</select></label><label class="field full-field income-only">Vendita collegata (facoltativa)<select name="dealId"><option value="">Nessuna vendita associata</option>${(state.deals||[]).map(d=>`<option value="${esc(d.id)}" ${p.dealId===d.id?'selected':''}>${esc(d.title)}</option>`).join('')}</select></label><label class="field expense-only">Categoria spesa<select name="category">${EXPENSE_CATEGORIES.map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field expense-only">Frequenza del costo<select name="frequency">${EXPENSE_FREQUENCIES.map(f=>`<option ${p.frequency===f?'selected':''}>${f}</option>`).join('')}</select></label></div><p class="hint" id="payment-source"></p><div id="royalty-preview"></div><div class="form-actions"><button type="button" class="btn" id="cancel">Annulla</button><button class="btn ${p.type==='income'?'income-action':'expense-action'}">${p.type==='income'?'Salva incasso':'Salva spesa'}</button></div></form>`);const form=$('#cash-form');const update=()=>{const income=form.elements.type.value==='income',client=(state.clients||[]).find(c=>c.id===form.elements.clientId.value);form.elements.clientId.required=income;form.querySelectorAll('.expense-only').forEach(e=>e.hidden=income);form.querySelectorAll('.income-only').forEach(e=>e.hidden=!income);const value=Number(form.elements.amount.value);$('#royalty-preview').innerHTML=income&&Number.isFinite(value)&&value>0?royaltyBreakdown(commissionSplit(value),true):'';$('#payment-source').textContent=income?`Provenienza: ${client?.source||'scegli un cliente con anagrafica completa'}. Inserisci il lordo: il 10% Italia e il 15% Platinum sul residuo sono detratti automaticamente.`:'Questa spesa aggiorna automaticamente le uscite e il margine. Non reinserirla nel registro risultati.'};form.elements.amount.oninput=update;form.elements.clientId.onchange=update;form.elements.dealId.onchange=()=>{const d=(state.deals||[]).find(d=>d.id===form.elements.dealId.value);if(d?.clientId)form.elements.clientId.value=d.clientId;update()};update();$('#cancel').onclick=()=>dialog.close();form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),client=(state.clients||[]).find(c=>c.id===f.get('clientId'));if(f.get('type')==='income'&&(!client||client.legacyIncomplete)){toast('Completa prima l’anagrafica e la provenienza del cliente.');return}const value={id:id||crypto.randomUUID(),type:f.get('type'),date:f.get('date'),description:f.get('description').trim(),amount:Number(f.get('amount')),clientId:f.get('clientId'),dealId:f.get('dealId'),category:f.get('category'),frequency:f.get('frequency')},next=structuredClone(state);next.cashEntries=next.cashEntries||[];if(id)next.cashEntries[next.cashEntries.findIndex(x=>x.id===id)]=value;else next.cashEntries.push(value);if(save(next)){dialog.close();toast(value.type==='income'?'Incasso salvato: quote RE/MAX e margine aggiornati.':'Spesa salvata separatamente: uscite e margine aggiornati.')}};}
function bindNative(){const on=(s,fn)=>{const e=$(s);if(e)e.onclick=fn};on('#new-client',()=>clientEditor());on('#new-income',()=>cashEditor());on('#new-expense-movement',()=>cashEditor(null,'','','expense'));on('#new-deal',()=>dealEditor());on('#import-clients',importBackup);const queryInput=$('#client-query');if(queryInput)queryInput.oninput=e=>{const pos=e.target.selectionStart;clientQuery=e.target.value;render();$('#client-query').focus();$('#client-query').setSelectionRange(pos,pos)};const filter=$('#client-source-filter');if(filter)filter.onchange=e=>{clientSource=e.target.value;render()};document.querySelectorAll('[data-client]').forEach(e=>e.onclick=()=>clientDetail(e.dataset.client));document.querySelectorAll('[data-edit-client]').forEach(e=>e.onclick=()=>clientEditor(e.dataset.editClient));document.querySelectorAll('[data-deal]').forEach(e=>e.onclick=()=>dealEditor(e.dataset.deal));document.querySelectorAll('[data-collect]').forEach(e=>e.onclick=()=>cashEditor(null,e.dataset.collect));document.querySelectorAll('[data-cash]').forEach(e=>e.onclick=()=>cashEditor(e.dataset.cash));document.querySelectorAll('[data-delete-cash]').forEach(e=>e.onclick=()=>confirm('Eliminare il movimento?','Incassi, spese e margine saranno ricalcolati automaticamente.',()=>{const next=structuredClone(state);next.cashEntries=next.cashEntries.filter(p=>p.id!==e.dataset.deleteCash);return save(next)}));document.querySelectorAll('[data-delete-deal]').forEach(e=>e.onclick=()=>confirm('Eliminare la vendita?','I pagamenti storici resteranno associati ai loro clienti, senza il riferimento alla vendita.',()=>{const next=structuredClone(state);next.deals=next.deals.filter(d=>d.id!==e.dataset.deleteDeal);(next.cashEntries||[]).forEach(p=>{if(p.dealId===e.dataset.deleteDeal)p.dealId=''});return save(next)}));}
function attributionReport(prefix){const a=revenueAttribution(baseState,prefix);const cells=s=>`<td>${amount(s.gross,'money')}</td><td>${amount(s.italiaFee,'money')}</td><td>${amount(s.platinumFee,'money')}</td><td>${amount(s.netRevenue,'money')}</td>`;return `<section class="panel attribution-report"><div class="panel-head"><div><h2>Da dove arrivano le provvigioni</h2><p>Lordo, quote fisse e netto per cliente e provenienza · ${esc(periodLabel(prefix))}</p></div></div><div class="attribution-sources">${a.bySource.map(s=>`<div><span>${esc(s.source)}</span><strong>${amount(s.netRevenue,'money')}</strong><small>Netto RE/MAX · lordo ${amount(s.gross,'money')}</small></div>`).join('')||'<p class="hint">Nessuna provvigione nel periodo.</p>'}</div><div class="table-wrap"><table><thead><tr><th>CLIENTE / FONTE</th><th>PAGAMENTI</th><th>LORDO</th><th>ITALIA 10%</th><th>PLATINUM 15% DOPO ITALIA</th><th>NETTO RE/MAX</th></tr></thead><tbody>${a.byClient.map(c=>`<tr><td>${esc(c.name)}<br><small>${esc(c.source)}${c.sourceDetails?' · '+esc(c.sourceDetails):''}</small></td><td>${c.count}</td>${cells(c)}</tr>`).join('')}${a.unattributed?`<tr><td>Incassi storici senza cliente</td><td>—</td>${cells(a.unattributedBreakdown)}</tr>`:''}</tbody><tfoot><tr><td colspan="2">TOTALE DEL PERIODO</td>${cells(a.totalBreakdown)}</tr></tfoot></table></div><p class="panel-footnote">Il netto per cliente e fonte è dopo Italia e Platinum, prima delle altre spese dell’agenzia.</p></section>`}

function resetDemo(){const cashEntries=(baseState.cashEntries||[]).filter(p=>!p.isDemo),deals=(baseState.deals||[]).filter(d=>!d.isDemo),clients=(baseState.clients||[]).filter(c=>!c.isDemo||cashEntries.some(p=>p.clientId===c.id)||deals.some(d=>d.clientId===c.id));return save({...baseState,demo:false,records:[],goals:{},expenseEntries:[],cashEntries,deals,clients});}

function royaltyBreakdown(split,compact=false){return `<section class="royalty-breakdown ${compact?'compact':''}" aria-label="Calcolo quote fisse RE/MAX"><div class="royalty-title"><strong>Quote fisse RE/MAX · calcolo automatico</strong><span>10% sul lordo, poi 15% sul residuo</span></div><div class="royalty-steps"><div data-fee="italia"><span>RE/MAX Italia · 10%</span><strong>− ${amount(split.italiaFee,'money')}</strong><small>10% di ${amount(split.gross,'money')}</small></div><div data-fee="base"><span>Residuo dopo Italia</span><strong>${amount(split.afterItalia,'money')}</strong><small>Base per RE/MAX Platinum</small></div><div data-fee="platinum"><span>RE/MAX Platinum · 15%</span><strong>− ${amount(split.platinumFee,'money')}</strong><small>15% del residuo dopo Italia</small></div><div data-fee="netto"><span>Netto dopo RE/MAX</span><strong>${amount(split.netRevenue,'money')}</strong><small>Da cui sottrarre le altre spese</small></div></div><p>Le quote sono già comprese nel calcolo del margine: non reinserirle tra le altre spese.</p></section>`}
function clientNet(id,prefix=''){return sumCommissionSplits((baseState.cashEntries||[]).filter(c=>c.type==='income'&&c.clientId===id&&c.date.startsWith(prefix)).map(c=>c.amount)).netRevenue}

function heroArtwork(){return `<div class="hero-art identity-art" aria-hidden="true"><span class="art-orbit orbit-one"></span><span class="art-orbit orbit-two"></span><span class="art-gold-square"></span><div class="brand-watermark"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" fill="none"><path d="m7 29 25-20 25 20" stroke="#8d244a" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><path d="M14 30v24h15V37h10v17h12V30" stroke="#b08530" stroke-width="3" stroke-linejoin="round"/><path d="M42 13V7h8v12M8 59h48" stroke="#b08530" stroke-width="2" stroke-linecap="round"/></svg></div><span class="art-caption">TEAM GUZZETTA / SPAZIO AL VALORE</span></div>`}
